"""Shared config-only feedback contract; output may be generated by this build.

An output must be a canonical public article path, never a hub, URL, draft,
private source, or traversal. File existence is a rollout/build validation,
not an identity rule: new articles need not already exist before rendering.
"""
import re


def feedback_eligible(entry, trip_slug, dest_slug=None):
    if not isinstance(entry, dict) or entry.get("feedback") is not True or entry.get("status") == "draft":
        return False
    dest = dest_slug or trip_slug
    identifier = entry.get("id")
    if not all(isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9_-]+", v) for v in (trip_slug, dest, identifier)):
        return False
    output = entry.get("output")
    return isinstance(output, str) and bool(re.fullmatch(
        r"docs/" + re.escape(dest) + r"/blog/[A-Za-z0-9_-]+\.html", output
    ))
